"""Research report with frozen-rule comparison, uncertainty, costs and full search ledger."""
from pathlib import Path
import html,json
import numpy as np
import research as r
def fmt(x,dec=2,suffix='',signed=False):
    return '—' if x is None else format(x,('+' if signed else '')+f'.{dec}f')+suffix
def table(rows,heads):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def row(title,m):
    return [html.escape(title),m['start']+' → '+m['end_exclusive'],m['trades'],fmt(m['win_rate_pct'],1,'%'),fmt(m['profit_factor']),fmt(m['return_pct'],2,'%',True),fmt(m['sharpe']),fmt(m['max_closed_dd_pct'],2,'%'),f"{m['max_win_streak']} / {m['max_loss_streak']}",m['missing']]
HEADS=['Version / period','Dates (end exclusive)','Trades','Win rate','PF','Return','Daily cash Sharpe','Closed DD','Win / loss streak','Missing windows']
def equity(variants):
    curves=[]
    for name,v in variants.items():
        trades=[t for t in v['trades'] if t['status']=='available'];dates=[r.pd.Timestamp(t['exit_utc']).timestamp() for t in trades];values=np.r_[10000,10000+np.cumsum([t['net_points'] for t in trades])];dates=[r.pd.Timestamp(r.PROTO['oos'][0],tz='UTC').timestamp()]+dates;curves.append((name,np.array(dates),values))
    low=min(y.min() for _,_,y in curves);high=max(y.max() for _,_,y in curves);a=r.pd.Timestamp(r.PROTO['oos'][0],tz='UTC').timestamp();z=r.pd.Timestamp(r.PROTO['oos'][1],tz='UTC').timestamp()
    paths=[]
    for name,x,y in curves:
        path=' '.join(('M' if i==0 else 'L')+f'{45+(t-a)/(z-a)*910:.2f},{260-(v-low)/(high-low or 1)*220:.2f}' for i,(t,v) in enumerate(zip(x,y)));color='#79e8c3' if name=='original' else '#fb788e';paths.append(f'<path d="{path}" stroke="{color}" fill="none" stroke-width="2.3"/>')
    return '<svg viewBox="0 0 1000 300" role="img" aria-label="Original and frozen candidate closed-balance equity, last two years">'+''.join(paths)+f'<text x="45" y="20" fill="#9cbbc0">${high:,.2f}</text><text x="45" y="288" fill="#9cbbc0">2024-10-14 · lowest ${low:,.2f}</text><text x="790" y="288" fill="#9cbbc0">2026-10-14</text></svg>'
def main():
    result=r.load_json('RESULTS.json');lock=result['final_candidate'];v=result['variants'];c=v['candidate'];orig=v['original'];search=r.load_json('SEARCH.json');wf=r.load_json('WALK-FORWARD.json');native=result['native'];fake=result['fake_market_summary'];audit=r.load_json('VALIDATION.json')
    assert audit['passed'] and audit['results_sha256']==r.sha(r.R/'RESULTS.json')
    content=['<header><p class="eyebrow">CALYX · CLOCK STRATEGY · RESEARCH COMPLETE</p><h1>No validated version emerged.</h1><p>The pre-holdout winner was <strong>'+html.escape(lock['label'])+'</strong>. It passed the development/validation preference screen but lost in the final two-year holdout. The original Thursday rule also lost. No OOS re-selection.</p><div class="warning">US500 CFD adaptation, not ES futures. Fixed 1.00 CFD lot, $10,000 reference balance; $1 per index point. No stop-loss or target. Returns are NOT a 1%-risk test, and no-stop exposure has no guaranteed maximum loss.</div></header>',
    '<section><h2>Frozen split and rules</h2>'+table([['Development','2020-01-01 → 2023-10-14','8,500 predeclared configurations, one-factor baseline, stability-first ranking'],['Validation','2023-10-14 → 2024-10-14','Fixed development shortlist, preferred gates, final candidate freeze'],['Final OOS','2024-10-14 → 2026-10-14','Two full calendar years; latest 3m/6m/1y diagnostic only']],['Stage','Dates (end exclusive)','Use'])+'<p>Original: Thursday long at 10:10 ET, close at 10:15. Frozen candidate: Tuesday short at 09:35 ET, close at 09:50. DST follows New York. No indicator, stop, target, trailing or discretionary filter was added. The search grid was frozen before reading holdout results; it is our reconstruction of 8,500 combinations, not the creator’s undisclosed grid.</p><p>Previously inspected 2020–2023 prices and prior selected video rules mean this is a retrospective parameter holdout, not a claim of completely untouched market evidence.</p></section>',
    '<section><h2>Original vs frozen candidate · API-bar reference</h2><p>Recorded broker spreads included: long buys ask/exits bid; short sells bid/exits ask. Every minute from entry through exit is required; missing eligible windows are not filled with stale quotes or counted as zero-return observations.</p>'+table([row('Original · development',lock['original_development']),row('Candidate · development',lock['development']),row('Original · validation',lock['original_validation']),row('Candidate · validation',lock['validation']),row('Original · final OOS',orig['oos']),row('Candidate · final OOS',c['oos'])],HEADS)+equity(v)+'<p><span style="color:#79e8c3">Green: original</span> · <span style="color:#fb788e">Red: frozen candidate</span>. Closed balance only; not floating equity.</p></section>',
    '<section><h2>Isolated MT5 execution check · same two-year OOS</h2><p>Tester-only EA refuses all live/demo charts. Fixed 1 lot, 150ms modelled execution delay. Native source was Exness-MT5Trial16; API source Exness-MT5Trial15. Tick/fill differences are shown rather than silently replacing the reference result. The tester reports <strong>39% real ticks</strong>; earlier missing ticks are simulated.</p>'+table([[x['name'],x['metadata']['trades'],fmt(x['metadata']['win_rate_pct'],1,'%'),fmt(x['metadata']['profit_factor']),fmt(x['metadata']['net_profit'],2,' USD',True),fmt(x['metadata']['return_pct'],2,'%',True),fmt(x['metadata']['comparable_daily_cash_sharpe']),fmt(x['metadata']['closed_dd_pct'],2,'%'),fmt(x['stats']['equity_dd_pct'],2,'%'),fmt(x['stats']['daily_equity_dd_pct'],2,'%'),x['metadata']['history_quality']] for x in native],['Version','Trades','Win rate','PF','Net','Return','Comparable daily Sharpe','Closed DD','Native tick equity DD','Daily tick equity DD','Quality'])+'<p>Use the comparable daily cash Sharpe above; MT5’s differently defined summary Sharpe is not mixed into the API comparison. Native candidate '+fmt(next(x for x in native if x['name']=='candidate-OOS')['metadata']['net_profit'],2,' USD',True)+' confirms a loss. Original native count is 100 versus 101 valid API windows; source-server/fill differences and the missing native date are retained in VALIDATION.json. Native equity metrics describe this mixed real/simulated path, not measured live risk.</p></section>',
    '<section><h2>Latest diagnostics · frozen candidate, no retuning</h2>'+table([row('Latest '+name,m) for name,m in c['recent'].items()]+[row('Last '+name,m) for name,m in c['windows'].items()]+[row('Full history · includes selection',c['full_history'])],HEADS)+'<p>3-/5-year and full-history results include development/selection dates. They are not independent OOS validation and should not override the failed final holdout.</p></section>',
    '<section><h2>Calendar-year breakdown · frozen candidate</h2>'+table([row(str(m['start'][:4])+(' · partial year' if m['end_exclusive']=='2026-10-14' else ''),m) for m in c['yearly']],HEADS)+'</section>',
    '<section><h2>Costs · both versions in final OOS</h2>'+table([[name,('Recorded spread' if m['extra_points']==0 else 'Recorded spread + '+fmt(m['extra_points'])+' extra points'),m['trades'],fmt(m['win_rate_pct'],1,'%'),fmt(m['profit_factor']),fmt(m['return_pct'],2,'%',True),fmt(m['sharpe'])] for name,variant in v.items() for m in variant['costs']],['Version','Cost case','Trades','Win rate','PF','Return','Daily Sharpe'])+'<p>The extra 0.60 and 1.10 index-point scenarios are assumptions, not measured broker slippage or commission. Live slippage evidence is absent and remains a failed promotion gate. For this CFD, one MT5 tick is 0.01 point; the scenario is not “two CFD ticks”. Current Pro zero-commission is an assumption, with historical commissions not reconstructed from the quote archive.</p></section>',
    '<section><h2>10,000-path Monte Carlo · frozen candidate OOS</h2>'+table([[b['block_calendar_weeks'],b['paths'],fmt(b['probability_profit_pct'],1,'%'),fmt(b['return_p05_pct'],2,'%',True),fmt(b['return_p50_pct'],2,'%',True),fmt(b['return_p95_pct'],2,'%',True),fmt(b['pf_p05']),fmt(b['dd_p95_pct'],2,'%')] for b in c['bootstrap']],['Block weeks','Paths','Profitable paths','Return P5','Median return','Return P95','PF P5','DD P95'])+'<p>Circular calendar-week blocks preserve weekday frequency. Each path uses the same resampled cash series for return, PF and drawdown; fixed lots, no synthetic compounding. These are conditional historical uncertainty scenarios, not future profit/funding probabilities. At tiny fixed 1-lot exposure the closed-cash breach estimate can be zero; that does not establish safe sizing or floating-equity loss limits. Original bootstrap is unavailable because three eligible API windows are missing.</p></section>',
    '<section><h2>Video checks plus added anti-overfitting checks</h2>'+table([['New data','FAIL','Frozen candidate OOS PF '+fmt(c['oos']['profit_factor'])+'; return '+fmt(c['oos']['return_pct'],2,'%',True)],['Next-door settings','FAIL',str(sum(n['metrics']['net_usd']>0 for n in result['oos_neighbors']))+'/'+str(len(result['oos_neighbors']))+' nearby rules profitable in OOS'],['Trading costs','FAIL','Even recorded-spread reference loses; extra-cost sensitivity worsens it'],['Fake market, entire 8500 family','FAIL','Search’s best observed development Sharpe '+fmt(fake['observed_best_sharpe'])+'; family p='+fmt(fake['best_search_family_p'],3)+'; fake-best median '+fmt(fake['fake_best_sharpe_p50'])+' / P95 '+fmt(fake['fake_best_sharpe_p95'])],['Selected-rule family p','FAIL','p='+fmt(fake['candidates'][str(lock['selected_id'])]['family_max_p'],3)+' after scanning 8500 rules; fixed-rule p alone is not selection-corrected'],['Deflated Sharpe','FAIL',fmt(c['development_dsr']['dsr_pct'],2,'%')+' nominal-independent-trial DSR; saved pipeline approximation '+fmt(c['development_dsr']['saved_pipeline']['deflated_sharpe_pct'],2,'%')],['CSCV search instability','Diagnostic',fmt(result['pbo_pct'],1,'%')+' PBO over 252 development partitions; one favorable diagnostic does not rescue other failures'],['Top-100 survival','Diagnostic',str(result['holdout_shortlist_profitable'])+'/100 frozen development shortlisted rules profitable in OOS; overlapping, not 100 independent experiments'],['Leakage and cash reconciliation','PASS',str(len(audit['checks']))+' independent data/accounting checks plus 15 synthetic unit tests; no future closes used for fills'],['Live promotion','REJECT','Missing measured slippage; only 39% real ticks; multiple statistical/economic failures']],['Check','Decision','Evidence'])+'<p>The joint null shares a calendar-week random sign across all times, holds and both directions. Gross moves change sign but spreads remain costs. It preserves observed volatility magnitudes and cross-rule dependence, under a sign-symmetry zero-drift assumption. It is not every possible fake-market model. DSR with 8,500 nominal independent trials is conservative for correlated rules; empirical family-max testing complements it.</p></section>',
    '<section><h2>Next-door table · candidate OOS</h2>'+table([row(r.label(n['parameters']),n['metrics']) for n in result['oos_neighbors']],HEADS)+'<h3>Move the weekday, keeping time/hold/direction fixed</h3>'+table([row(n['reference']+' neighbor: '+r.label(n['parameters']),n['metrics']) for n in result['weekday_neighbors']],HEADS)+'<p>Adjacent-day checks are diagnostic only. Their results cannot be used to replace the frozen final candidate.</p></section>',
    '<section><h2>Additional expanding walk-forward diagnostic · development only</h2><p>'+html.escape(wf['scope'])+'</p>'+table([row(r.label(f['parameters']),f['test']) for f in wf['folds']],HEADS)+'<p>Aggregate changing-rule walk-forward: '+str(wf['aggregate']['trades'])+' trades, PF '+fmt(wf['aggregate']['pf'])+', '+fmt(wf['aggregate']['return_pct'],2,'%',True)+'. This is a diagnostic of the search procedure, not the final fixed candidate’s P/L and was not used to rescue or retune it.</p></section>',
    '<section><h2>Every candidate trade · final OOS</h2>'+table([[t['date'],t['entry_utc'][11:19]+' UTC',t['exit_utc'][11:19]+' UTC',fmt(t.get('entry')),fmt(t.get('exit')),fmt(t.get('spread_points')),fmt(t.get('net_points'),2,'',True),fmt(t.get('mae_points')),fmt(t.get('mfe_points')),html.escape(t['status'])] for t in c['trades']],['Date','Entry','Exit','Sell fill','Buy exit','Exit spread','Net points / USD','M1 adverse','M1 favorable','Coverage'])+'<p>MAE/MFE are indicative M1 extremes, not tick ordering or executable optimal stops. Exit-minute later highs/lows are excluded. Futures multipliers, liquidity, fees and roll effects are not represented.</p></section>',
    '<section><h2>Full development search ledger · 8,500 recorded rules</h2><p>Search and filter below. All rows remain available; holdout results are not used to rank or choose the final candidate.</p><input id="filter" placeholder="Search weekday, time or side" aria-label="Filter search ledger"><button id="prev">Previous</button><button id="next">Next</button><span id="count"></span><div id="search-table"></div></section>',
    '<section><h2>Promotion gates</h2>'+table([[html.escape(k.replace('_',' ')),('PASS' if val else 'FAIL')] for k,val in result['gates'].items()],['Gate','Result'])+'<p>There is no validated “best” version. The best pre-holdout candidate is rejected, not replaced by an OOS winner. Further searches on these two years would consume the holdout and require a new documented experiment plus genuinely new forward data. Live EAs, BATs and portfolio membership are unchanged by this study.</p></section>',
    '<footer><p>Reproducible source files, split, candidate freeze, complete search, null distribution, raw trade ledgers, native journals and verification hashes are saved alongside this report.</p><p>Method references: <a href="https://www.davidhbailey.com/dhbpapers/deflated-sharpe.pdf">Bailey &amp; López de Prado — Deflated Sharpe Ratio</a> · <a href="https://www.davidhbailey.com/dhbpapers/backtest-prob.pdf">Bailey et al. — Probability of Backtest Overfitting</a> · <a href="https://www.mql5.com/en/docs/python_metatrader5/mt5copyratesrange_py">MetaQuotes quote-history API</a>.</p></footer>']
    grid=[]
    for i in search['rank_by_development']:
        s=search['configurations'][i];d=s['development'];grid.append([i,r.label(s),int(d['trades']),round(d['win_rate'],2),None if d['pf'] is None else round(d['pf'],3),round(d['net']/100,3),round(d['sharpe'],3),round(s['dev_neighbor_p25_sharpe'],3),round(s['dev_neighbor_positive_share']*100),s['development_gate']])
    js='''const rows=JSON.parse(document.getElementById('search-data').textContent);let page=0;const per=100;function draw(){const q=document.getElementById('filter').value.toLowerCase();const a=rows.filter(x=>x[1].toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(a.length/per)-1)));const sub=a.slice(page*per,(page+1)*per);document.getElementById('count').textContent=` ${a.length} rules · page ${page+1}/${Math.max(1,Math.ceil(a.length/per))}`;document.getElementById('search-table').innerHTML='<div class="scroll"><table><thead><tr>'+['ID','Rule','Trades','Win %','PF','Return %','Daily Sharpe','Neighbor P25 Sharpe','Positive neighbors %','Dev gate'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+sub.map(x=>'<tr>'+x.map(c=>'<td>'+(c===null?'—':c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}document.getElementById('filter').oninput=()=>{page=0;draw()};document.getElementById('prev').onclick=()=>{page--;draw()};document.getElementById('next').onclick=()=>{page++;draw()};draw();'''
    css='''*{box-sizing:border-box}body{margin:0;background:#071616;color:#d9e8e8;font:15px/1.65 Segoe UI,Arial,sans-serif}main{max-width:1280px;margin:auto;padding:36px 24px}header,section,footer{background:#0b2020;border:1px solid #264543;border-radius:15px;padding:26px;margin-bottom:22px}h1{font-size:38px;line-height:1.2;margin:8px 0 18px;color:#fff}h2{font-size:24px;margin:0 0 15px;color:#a5f5d9}p{max-width:1100px;color:#acc5c5}.eyebrow{letter-spacing:2px;color:#70e6c2;font-size:12px}.warning{border:1px solid #8d7440;background:#302c1e;color:#ffe0a1;border-radius:10px;padding:16px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th{text-align:left;color:#8ff1d0;background:#10302d}th,td{padding:11px 12px;border-bottom:1px solid #264541}tr:nth-child(even){background:#0b2524}td:nth-child(2){white-space:normal;min-width:170px}svg{width:100%;height:auto;background:#061a19;border-radius:10px;margin-top:20px}input,button{padding:11px;background:#0e3430;color:#d4f7eb;border:1px solid #3e756a;border-radius:7px;margin:6px}input{min-width:300px}a{color:#8ff1d0}footer{font-size:13px}@media(max-width:700px){main{padding:12px}header,section{padding:17px}h1{font-size:29px}input{min-width:200px}}'''
    doc='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>US500 Full Pipeline · No validated version</title><style>'+css+'</style><main>'+''.join(content)+'</main><script type="application/json" id="search-data">'+json.dumps(r.safe(grid),allow_nan=False)+'</script><script>'+js+'</script></html>'
    (r.R/'Results.html').write_text(doc,encoding='utf-8');r.save('REPORT-VERIFICATION.json',dict(html_sha256=r.sha(r.R/'Results.html'),results_sha256=r.sha(r.R/'RESULTS.json'),validation_sha256=r.sha(r.R/'VALIDATION.json'),search_rows=len(grid),trade_rows=len(c['trades']),native_reports=len(native),no_live_changes=True));print('Report ready: '+str(r.R/'Results.html'))
if __name__=='__main__':main()
